  def render_artifact_type_icon(artifact_type)
    path_data = ARTIFACT_TYPE_ICONS.fetch(artifact_type, DEFAULT_ICON_PATH)
    tag.svg(
      class: "h-6 w-6 text-indigo-600",
      fill: "none",
      viewBox: "0 0 24 24",
      "stroke-width": "1.5",
      stroke: "currentColor",
      "aria-hidden": "true"
    ) do
      tag.path("stroke-linecap": "round", "stroke-linejoin": "round", d: path_data)
    end
  end

  def artifact_type_label(artifact_type)
    artifact_type.titleize.pluralize
  end
